/* ===== nico 日记卡 =====
①「水印文字」填角色名 ②「头像类型」选「角色」③ 作者/用户名留空
 ===== */
.be-card.be-custom{display:block!important;width:100%!important;max-width:460px!important;min-height:260px!important;padding:128px 28px 96px!important;position:relative!important;box-sizing:border-box!important;background:var(--be-card-bg,#ffffff)!important;color:var(--be-card-fg,#111)!important;border-radius:0!important;border:none!important;box-shadow:none!important;text-align:left!important;overflow:hidden!important;font-family:-apple-system,BlinkMacSystemFont,"PingFang SC","Hiragino Sans GB","Microsoft YaHei","Segoe UI",sans-serif!important;margin:0 auto!important}
.be-card.be-custom::before{content:''!important;position:absolute!important;top:15px!important;left:18px!important;width:26px!important;height:26px!important;background:url('data:image/svg+xml,%3Csvg%20xmlns=%22http://www.w3.org/2000/svg%22%20width=%2224%22%20height=%2224%22%20viewBox=%220%200%2024%2024%22%20fill=%22none%22%20stroke=%22%23333%22%20stroke-width=%222%22%20stroke-linecap=%22round%22%20stroke-linejoin=%22round%22%3E%3Cpath%20d=%22M15%2018l-6-6%206-6%22/%3E%3C/svg%3E') center/contain no-repeat!important;z-index:3!important}
.be-card.be-custom::after{content:url('data:image/svg+xml,%3Csvg%20xmlns=%22http://www.w3.org/2000/svg%22%20width=%2216%22%20height=%2216%22%20viewBox=%220%200%2024%2024%22%20fill=%22%23a0a0a0%22%3E%3Ccircle%20cx=%2212%22%20cy=%2212%22%20r=%221.8%22/%3E%3Ccircle%20cx=%2219%22%20cy=%2212%22%20r=%221.8%22/%3E%3Ccircle%20cx=%225%22%20cy=%2212%22%20r=%221.8%22/%3E%3C/svg%3E')!important;position:absolute!important;bottom:34px!important;left:75%!important;width:25%!important;height:22px!important;display:flex!important;align-items:center!important;justify-content:center!important;z-index:4!important}
.be-card.be-custom .be-watermark{position:absolute!important;top:0!important;left:0!important;right:0!important;height:56px!important;text-align:center!important;line-height:56px!important;font-size:19px!important;font-weight:600!important;color:var(--be-card-fg,#111)!important;opacity:1!important;margin:0!important;background:#ececec!important;border-bottom:6px solid #d8d8d8!important;z-index:2!important}
.be-card.be-custom .be-watermark::after{content:'sillytavern ·日记'!important;font-weight:600!important;color:var(--be-card-fg,#111)!important;margin-left:4px!important}
.be-card.be-custom .be-head,.be-card.be-custom .be-meta,.be-card.be-custom .be-source{display:contents!important}
/* 左右侧边线 */
.be-card.be-custom .be-quote::before{content:''!important;position:absolute!important;top:56px!important;bottom:0!important;left:0!important;width:6px!important;background:#d8d8d8!important;z-index:0!important}
.be-card.be-custom .be-source::after{content:''!important;position:absolute!important;top:56px!important;bottom:0!important;right:0!important;width:6px!important;background:#d8d8d8!important;z-index:0!important}
.be-card.be-custom .be-char-avatar{display:block!important;position:absolute!important;top:66px!important;left:20px!important;width:52px!important;height:52px!important;border-radius:50%!important;background-size:cover!important;background-position:center!important;border:1px solid rgba(0,0,0,0.04)!important;box-shadow:none!important;cursor:pointer!important;z-index:1!important}
.be-card.be-custom .be-avatar{display:none!important}
.be-card.be-custom .be-source .author{position:absolute!important;top:70px!important;left:80px!important;right:28px!important;font-size:19px!important;font-weight:700!important;color:var(--be-card-fg,#111)!important;letter-spacing:-0.3px!important;white-space:nowrap!important;overflow:hidden!important;text-overflow:ellipsis!important;margin:0!important;line-height:24px!important;z-index:1!important}
.be-card.be-custom .be-source .author::before{content:none!important}
.be-card.be-custom .be-source .author::after{display:none!important}
.be-card.be-custom .be-source .be-mask-block{background:transparent!important;color:var(--be-card-fg,#111)!important}
.be-card.be-custom .be-name{position:absolute!important;top:94px!important;left:80px!important;right:28px!important;font-size:14px!important;color:#888!important;white-space:nowrap!important;overflow:hidden!important;text-overflow:ellipsis!important;margin:0!important;line-height:18px!important;z-index:1!important}
.be-card.be-custom 
.be-card.be-custom .be-name .be-mask-block{display:none!important}
.be-card.be-custom .be-quote{color:var(--be-card-fg,#1a1a1a)!important;font-size:var(--be-quote-size,19px)!important;line-height:var(--be-quote-lh,1.65)!important;text-align:left!important;padding:0 0 8px!important;word-wrap:break-word!important;overflow-wrap:break-word!important;margin:0!important}
.be-card.be-custom .be-quote p{text-indent:0!important;margin:0 0 0.4em!important;word-wrap:break-word!important;overflow-wrap:break-word!important}
.be-card.be-custom .be-thought-main{font-size:19px!important;font-weight:700!important;line-height:1.5!important;color:var(--be-card-fg,#111)!important;margin:0 0 8px!important}
.be-card.be-custom .be-quote-orig{position:absolute!important;right:28px!important;bottom:8px!important;left:auto!important;text-align:right!important;font-size:12px!important;line-height:1.5!important;color:#b8b8b8!important;border-left:none!important;padding-left:0!important;margin:0!important;max-width:72%!important;white-space:nowrap!important;overflow:hidden!important;text-overflow:ellipsis!important;z-index:1!important}
.be-card.be-custom .be-quote-orig::before{content:none!important}
/* 时间戳 */
.be-card.be-custom .be-head::before{content:''!important;position:absolute!important;left:20px!important;bottom:64px!important;width:16px!important;height:16px!important;background:url('data:image/svg+xml,%3Csvg%20xmlns=%22http://www.w3.org/2000/svg%22%20width=%2224%22%20height=%2224%22%20viewBox=%220%200%2024%2024%22%20fill=%22none%22%20stroke=%22%23a0a0a0%22%20stroke-width=%222%22%20stroke-linecap=%22round%22%20stroke-linejoin=%22round%22%3E%3Ccircle%20cx=%2212%22%20cy=%2212%22%20r=%229%22/%3E%3Cpath%20d=%22M12%207v5l3%203%22/%3E%3C/svg%3E') center/contain no-repeat!important;z-index:1!important}
.be-card.be-custom .be-date{position:absolute!important;bottom:64px!important;left:48px!important;font-size:14px!important;color:#a0a0a0!important;white-space:nowrap!important;overflow:hidden!important;text-indent:0!important;width:140px!important;height:16px!important;line-height:16px!important;margin:0!important;z-index:1!important}
.be-card.be-custom .be-date-cn{position:absolute!important;bottom:64px!important;left:132px!important;right:28px!important;font-size:0!important;margin:0!important;white-space:nowrap!important;line-height:16px!important;height:16px!important;z-index:1!important}
.be-card.be-custom .be-date-cn::before{content:'· 来到地球第 '!important;font-size:14px!important;color:#a0a0a0!important;line-height:16px!important}
.be-card.be-custom .be-date-cn::after{content:'7210 天'!important;font-size:14px!important;color:#888!important;font-weight:600!important;line-height:16px!important}
/* 分隔线 */
.be-card.be-custom .be-source .title,.be-card.be-custom .be-source .chapter{display:none!important}
.be-card.be-custom .be-source::before{content:''!important;position:absolute!important;left:6px!important;right:6px!important;bottom:34px!important;height:1px!important;background:#f0f0f0!important;z-index:1!important}
/* 底栏四项 - SVG图标 */
.be-card.be-custom .be-head::after{content:url('data:image/svg+xml,%3Csvg%20xmlns=%22http://www.w3.org/2000/svg%22%20width=%2216%22%20height=%2216%22%20viewBox=%220%200%2024%2024%22%20fill=%22none%22%20stroke=%22%23a0a0a0%22%20stroke-width=%221.8%22%20stroke-linecap=%22round%22%20stroke-linejoin=%22round%22%3E%3Cpath%20d=%22M20.84%204.61a5.5%205.5%200%200%200-7.78%200L12%205.67l-1.06-1.06a5.5%205.5%200%200%200-7.78%207.78l1.06%201.06L12%2021.23l7.78-7.78%201.06-1.06a5.5%205.5%200%200%200%200-7.78z%22/%3E%3C/svg%3E')  ' 喜欢'!important;position:absolute!important;bottom:34px!important;left:6px!important;width:calc(25% - 6px)!important;height:22px!important;font-size:13px!important;color:#a0a0a0!important;line-height:1!important;text-align:center!important;border-right:1px solid #eaeaea!important;box-sizing:border-box!important;letter-spacing:0!important;overflow:hidden!important;display:flex!important;align-items:center!important;justify-content:center!important;gap:4px!important;z-index:1!important}
.be-card.be-custom .be-meta::after{content:url('data:image/svg+xml,%3Csvg%20xmlns=%22http://www.w3.org/2000/svg%22%20width=%2216%22%20height=%2216%22%20viewBox=%220%200%2024%2024%22%20fill=%22none%22%20stroke=%22%23a0a0a0%22%20stroke-width=%221.8%22%20stroke-linecap=%22round%22%20stroke-linejoin=%22round%22%3E%3Cpath%20d=%22M21%2011.5a8.38%208.38%200%200%201-.9%203.8%208.5%208.5%200%200%201-7.6%204.7%208.38%208.38%200%200%201-3.8-.9L3%2021l1.9-5.7a8.38%208.38%200%200%201-.9-3.8%208.5%208.5%200%200%201%204.7-7.6%208.38%208.38%200%200%201%203.8-.9h.5a8.48%208.48%200%200%201%208%208v.5z%22/%3E%3C/svg%3E')  ' 小纸条'!important;position:absolute!important;bottom:34px!important;left:25%!important;width:25%!important;height:22px!important;font-size:13px!important;color:#a0a0a0!important;line-height:1!important;text-align:center!important;border-right:1px solid #eaeaea!important;box-sizing:border-box!important;letter-spacing:0!important;overflow:hidden!important;display:flex!important;align-items:center!important;justify-content:center!important;gap:4px!important;z-index:1!important}
.be-card.be-custom .be-quote::after{content:url('data:image/svg+xml,%3Csvg%20xmlns=%22http://www.w3.org/2000/svg%22%20width=%2216%22%20height=%2216%22%20viewBox=%220%200%2024%2024%22%20fill=%22none%22%20stroke=%22%23a0a0a0%22%20stroke-width=%221.8%22%20stroke-linecap=%22round%22%20stroke-linejoin=%22round%22%3E%3Cpath%20d=%22M21%2015v4a2%202%200%200%201-2%202H5a2%202%200%200%201-2-2v-4%22/%3E%3Cpolyline%20points=%227%2010%2012%2015%2017%2010%22/%3E%3Cline%20x1=%2212%22%20y1=%2215%22%20x2=%2212%22%20y2=%223%22/%3E%3C/svg%3E')  ' 存为图片'!important;position:absolute!important;bottom:34px!important;left:50%!important;width:25%!important;height:22px!important;font-size:13px!important;color:#a0a0a0!important;line-height:1!important;text-align:center!important;border-right:1px solid #eaeaea!important;box-sizing:border-box!important;letter-spacing:0!important;overflow:hidden!important;display:flex!important;align-items:center!important;justify-content:center!important;gap:4px!important;z-index:1!important}
.be-card.be-custom .be-mask-block{background:currentColor!important}

comments:
/* ===== icity 日记 · 评述模块（白底一体，分割线分隔） ===== */
.be-comments {
  background: #ffffff;
  border-top: 1px solid #ececec;
  font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", "Segoe UI", sans-serif;
}
.be-comment {
  display: flex;
  gap: 9px;
  padding: 10px 28px;
  border-bottom: 1px solid #f5f5f5;
}
.be-comment:last-child { border-bottom: none; }
.be-comment-avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background-size: cover;
  background-position: center;
  background-color: #f0f0f0;
  flex-shrink: 0;
  margin-top: 1px;
}
.be-comment-main { flex: 1; min-width: 0; }
.be-comment-meta { display: flex; align-items: baseline; flex-wrap: wrap; gap: 3px 6px; }
.be-comment-name { font-size: 12.5px; color: #1a1a1a; font-weight: 700; }
.be-comment-id { font-size: 11px; color: #888; }
.be-comment-time { font-size: 11px; color: #a0a0a0; }
.be-comment-text { font-size: 13px; color: #333; line-height: 1.6; margin-top: 2px; white-space: pre-wrap; overflow-wrap: break-word; }
.be-comment[data-kind="user"] .be-comment-name { color: #1a1a1a; text-decoration: underline; text-underline-offset: 3px; }
